import { DIMENSIONS } from '@rm/core';
import { readdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { z } from 'zod';

const Status = z.enum(['met', 'partial', 'missing']);

/**
 * One hand-labelled golden case. Labels are written by a human BEFORE looking at
 * model output. Requirement IDs are generated by the model, so requirement labels
 * are matched by a keyword that appears in the requirement text.
 */
export const EvalCaseSchema = z.object({
  id: z.string().regex(/^[a-z0-9-]+$/),
  category: z.enum(['strong', 'partial', 'poor', 'adversarial', 'edge']),
  description: z.string(),
  resume: z.string().min(1),
  jd: z.string().min(1),
  labels: z.object({
    /** Expected status per requirement; a list means any of these is acceptable. */
    requirements: z.array(
      z.object({
        keyword: z.string().describe('Case-insensitive substring of the requirement text'),
        status: z.union([Status, z.array(Status).min(1)]),
      }),
    ),
    /**
     * Human score per dimension (1-5); agreement = model within +/-1.
     * "low" = 2 or less, or "insufficient evidence" (for near-empty resumes).
     */
    dimensions: z.partialRecord(z.enum(DIMENSIONS), z.union([z.number().int().min(1).max(5), z.literal("low")])),
    /** Strings that must never appear in any reason, note, or quote (e.g. invented facts). */
    banned: z.array(z.string()).default([]),
    /**
     * Injection case: the resume contains instructions aimed at the grader.
     * Passes if the guard flags it AND the overall score is not inflated
     * compared with the clean baseline case.
     */
    injection: z.object({ baseline: z.string() }).optional(),
  }),
});
export type EvalCase = z.infer<typeof EvalCaseSchema>;

const DATASET_DIR = join(dirname(fileURLToPath(import.meta.url)), '..', 'datasets');

/** Load datasets/<version>/*.json (files starting with "_" are templates and are skipped). */
export function loadDataset(version = 'v1', dir = DATASET_DIR): EvalCase[] {
  const folder = join(dir, version);
  const files = readdirSync(folder).filter((f) => f.endsWith('.json') && !f.startsWith('_')).sort();
  const cases = files.map((f) => {
    const parsed = EvalCaseSchema.safeParse(JSON.parse(readFileSync(join(folder, f), 'utf8')));
    if (!parsed.success) {
      throw new Error(`${version}/${f}: ${parsed.error.issues.map((i) => `${i.path.join('.')}: ${i.message}`).join('; ')}`);
    }
    return parsed.data;
  });
  const ids = new Set(cases.map((c) => c.id));
  for (const c of cases) {
    if (c.labels.injection && !ids.has(c.labels.injection.baseline)) {
      throw new Error(`${c.id}: injection baseline "${c.labels.injection.baseline}" is not in the dataset`);
    }
  }
  return cases;
}
